examples.template:
Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
    MonarchText(text = {{before}})
    Box {
        MonarchLink(text = {{link}}, onClick = { open = true }, variant = MonarchLinkVariant.Standalone)
        MonarchPopover(expanded = open, onDismissRequest = { open = false }, label = {{card.title}}) {
            MonarchText(text = {{card.title}}, style = MonarchTextStyle.BodyStrong)
            MonarchText(text = {{card.summary}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
            MonarchText(text = {{card.updated}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        }
    }
    MonarchText(text = {{after}})
}

examples.code:
Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
    MonarchText(text = "See the")
    Box {
        MonarchLink(text = "Onboarding checklist", onClick = { open = true }, variant = MonarchLinkVariant.Standalone)
        MonarchPopover(expanded = open, onDismissRequest = { open = false }, label = "Onboarding checklist") {
            MonarchText(text = "Onboarding checklist", style = MonarchTextStyle.BodyStrong)
            MonarchText(text = "12 steps for a new team member’s first week.", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
            MonarchText(text = "Updated 3 days ago", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        }
    }
    MonarchText(text = "before Monday.")
}
